function OtelForgePure(){
  var KIND = {
    0:'UNSPECIFIED', 1:'INTERNAL', 2:'SERVER', 3:'CLIENT', 4:'PRODUCER', 5:'CONSUMER',
    'SPAN_KIND_UNSPECIFIED':'UNSPECIFIED', 'SPAN_KIND_INTERNAL':'INTERNAL',
    'SPAN_KIND_SERVER':'SERVER', 'SPAN_KIND_CLIENT':'CLIENT',
    'SPAN_KIND_PRODUCER':'PRODUCER', 'SPAN_KIND_CONSUMER':'CONSUMER'
  };
  var STATUS = {
    0:'UNSET', 1:'OK', 2:'ERROR',
    'STATUS_CODE_UNSET':'UNSET', 'STATUS_CODE_OK':'OK', 'STATUS_CODE_ERROR':'ERROR'
  };
  // 已被 stable 语义约定取代的旧键
  var RENAMED = {
    'http.method':'http.request.method',
    'http.status_code':'http.response.status_code',
    'http.url':'url.full',
    'http.target':'url.path',
    'http.scheme':'url.scheme',
    'http.host':'server.address',
    'http.user_agent':'user_agent.original',
    'http.request_content_length':'http.request.body.size',
    'http.response_content_length':'http.response.body.size',
    'net.peer.name':'server.address',
    'net.peer.ip':'network.peer.address',
    'net.peer.port':'server.port',
    'net.host.name':'server.address',
    'net.host.port':'server.port',
    'net.transport':'network.transport',
    'net.sock.peer.addr':'network.peer.address',
    'db.connection_string':'server.address',
    'db.user':'db.user (已移除，别再上报凭据类信息)',
    'db.statement':'db.query.text',
    'db.operation':'db.operation.name',
    'db.sql.table':'db.collection.name',
    'messaging.destination':'messaging.destination.name',
    'messaging.protocol':'network.protocol.name',
    'messaging.url':'server.address',
    'faas.execution':'faas.invocation_id',
    'rpc.grpc.status_code':'rpc.grpc.status_code'
  };
  // 疑似把机密写进属性
  var SECRET_RE = /(authorization|password|passwd|secret|token|api[-_.]?key|credential|cookie|session[-_.]?id|private[-_.]?key)/i;
  var SECRET_VAL = /(^bearer\s|^basic\s|ghp_[A-Za-z0-9]{20,}|sk-[A-Za-z0-9]{20,}|AKIA[0-9A-Z]{16}|eyJ[A-Za-z0-9_-]{10,}\.)/i;
  // 每个 span kind 建议具备的必填资源 / 属性
  var REQUIRED_RESOURCE = ['service.name'];
  var RECOMMENDED_RESOURCE = ['service.version', 'deployment.environment.name', 'service.namespace',
                              'telemetry.sdk.name', 'telemetry.sdk.language'];
  var HEX16 = /^[0-9a-f]{16}$/;
  var HEX32 = /^[0-9a-f]{32}$/;
  var ZERO32 = '00000000000000000000000000000000';
  var ZERO16 = '0000000000000000';

  function isObj(x){ return x && typeof x === 'object' && !(x instanceof Array); }
  function num(x){
    if (x == null) return null;
    if (typeof x === 'number') return x;
    var s = String(x).trim();
    if (!/^-?[0-9]+$/.test(s)) return null;
    return Number(s);
  }
  function anyValue(v){
    // OTLP/JSON 的 AnyValue：{stringValue|intValue|boolValue|doubleValue|arrayValue|kvlistValue|bytesValue}
    if (!isObj(v)) return v;
    if ('stringValue' in v) return v.stringValue;
    if ('intValue' in v) return num(v.intValue);
    if ('boolValue' in v) return !!v.boolValue;
    if ('doubleValue' in v) return Number(v.doubleValue);
    if ('bytesValue' in v) return '<bytes>';
    if ('arrayValue' in v){
      var arr = (v.arrayValue && v.arrayValue.values) || [];
      return arr.map(anyValue);
    }
    if ('kvlistValue' in v){
      var o = {}, kvs = (v.kvlistValue && v.kvlistValue.values) || [];
      for (var i = 0; i < kvs.length; i++) o[kvs[i].key] = anyValue(kvs[i].value);
      return o;
    }
    return null;
  }
  function attrMap(list){
    var out = {};
    if (!(list instanceof Array)) return out;
    for (var i = 0; i < list.length; i++){
      var kv = list[i];
      if (!isObj(kv) || kv.key == null) continue;
      out[String(kv.key)] = anyValue(kv.value);
    }
    return out;
  }
  function nano(x){
    var n = num(x);
    return n == null ? null : n;
  }
  function fmtDur(ns){
    if (ns == null) return '—';
    if (ns < 1000) return ns + ' ns';
    if (ns < 1e6) return (ns / 1000).toFixed(2) + ' µs';
    if (ns < 1e9) return (ns / 1e6).toFixed(2) + ' ms';
    return (ns / 1e9).toFixed(3) + ' s';
  }

  // ==================== 解析 ====================
  function parse(text){
    var raw = String(text == null ? '' : text).trim();
    if (!raw) return {error:'请粘贴 OTLP/JSON 格式的 trace 数据（ExportTraceServiceRequest 或 resourceSpans 数组）'};
    var doc;
    try { doc = JSON.parse(raw); }
    catch (e){ return {error:'JSON 解析失败：' + e.message}; }

    var rs = null;
    if (doc instanceof Array) rs = doc;
    else if (isObj(doc)){
      rs = doc.resourceSpans || doc.resource_spans || null;
      if (!rs && (doc.spans || doc.scopeSpans || doc.scope_spans)){
        // 允许直接丢一段 resourceSpans 条目进来
        rs = [doc];
      }
    }
    if (!(rs instanceof Array)) return {error:'没有找到 resourceSpans：OTLP/JSON 顶层应当是 {"resourceSpans":[...]} 或 resourceSpans 数组本身'};
    if (!rs.length) return {error:'resourceSpans 是空数组，没有可分析的 span'};

    var spans = [], resources = [], scopes = {};
    for (var i = 0; i < rs.length; i++){
      var r = rs[i] || {};
      var res = attrMap((r.resource && (r.resource.attributes)) || []);
      var resIdx = resources.length;
      resources.push({attrs:res, dropped:num((r.resource && r.resource.droppedAttributesCount) || 0) || 0, spanCount:0});
      var ss = r.scopeSpans || r.scope_spans || r.instrumentationLibrarySpans || [];
      if (!(ss instanceof Array)) continue;
      for (var j = 0; j < ss.length; j++){
        var sc = ss[j] || {};
        var scope = sc.scope || sc.instrumentationLibrary || {};
        var scopeName = scope.name || '(匿名 scope)';
        var scopeVer = scope.version || '';
        scopes[scopeName] = scopes[scopeName] || {name:scopeName, version:scopeVer, count:0};
        var list = sc.spans || [];
        if (!(list instanceof Array)) continue;
        for (var k = 0; k < list.length; k++){
          var s = list[k] || {};
          var start = nano(s.startTimeUnixNano != null ? s.startTimeUnixNano : s.start_time_unix_nano);
          var end = nano(s.endTimeUnixNano != null ? s.endTimeUnixNano : s.end_time_unix_nano);
          var st = s.status || {};
          var kindRaw = s.kind != null ? s.kind : 0;
          var evs = (s.events || []).map(function(e){
            return {name:e.name || '', time:nano(e.timeUnixNano != null ? e.timeUnixNano : e.time_unix_nano),
                    attrs:attrMap(e.attributes || [])};
          });
          var lks = (s.links || []).map(function(l){
            return {traceId:String(l.traceId || l.trace_id || ''), spanId:String(l.spanId || l.span_id || ''),
                    attrs:attrMap(l.attributes || [])};
          });
          spans.push({
            traceId: String(s.traceId != null ? s.traceId : (s.trace_id || '')).toLowerCase(),
            spanId: String(s.spanId != null ? s.spanId : (s.span_id || '')).toLowerCase(),
            parentSpanId: String(s.parentSpanId != null ? s.parentSpanId : (s.parent_span_id || '')).toLowerCase(),
            name: s.name == null ? '' : String(s.name),
            kind: KIND[kindRaw] || String(kindRaw),
            start: start, end: end,
            dur: (start != null && end != null) ? end - start : null,
            status: STATUS[st.code != null ? st.code : 0] || 'UNSET',
            statusMsg: st.message || '',
            attrs: attrMap(s.attributes || []),
            events: evs, links: lks,
            droppedAttrs: num(s.droppedAttributesCount || s.dropped_attributes_count || 0) || 0,
            droppedEvents: num(s.droppedEventsCount || s.dropped_events_count || 0) || 0,
            droppedLinks: num(s.droppedLinksCount || s.dropped_links_count || 0) || 0,
            resIdx: resIdx, scope: scopeName,
            service: res['service.name'] == null ? '' : String(res['service.name'])
          });
          resources[resIdx].spanCount++;
          scopes[scopeName].count++;
        }
      }
    }
    if (!spans.length) return {error:'解析成功但一个 span 都没有：检查 scopeSpans[].spans 是否为空'};
    return {spans:spans, resources:resources, scopes:scopes};
  }

  // ==================== 链路重建 ====================
  function buildTrees(spans){
    var byId = {}, i;
    for (i = 0; i < spans.length; i++) if (spans[i].spanId) byId[spans[i].spanId] = spans[i];
    var traces = {};
    for (i = 0; i < spans.length; i++){
      var t = spans[i].traceId || '(缺 traceId)';
      traces[t] = traces[t] || {traceId:t, spans:[], roots:[], orphans:[]};
      traces[t].spans.push(spans[i]);
    }
    var out = [];
    Object.keys(traces).forEach(function(tid){
      var tr = traces[tid];
      var local = {};
      tr.spans.forEach(function(s){ if (s.spanId) local[s.spanId] = s; s.children = []; });
      tr.spans.forEach(function(s){
        if (!s.parentSpanId || s.parentSpanId === ZERO16){ tr.roots.push(s); return; }
        var p = local[s.parentSpanId];
        if (p) p.children.push(s);
        else { tr.orphans.push(s); }
      });
      // 时间与深度
      var mn = null, mx = null;
      tr.spans.forEach(function(s){
        if (s.start != null && (mn == null || s.start < mn)) mn = s.start;
        if (s.end != null && (mx == null || s.end > mx)) mx = s.end;
      });
      tr.start = mn; tr.end = mx;
      tr.duration = (mn != null && mx != null) ? mx - mn : null;
      var depth = 0, cyc = false, guard = 0;
      function walk(s, d, seen){
        guard++;
        if (guard > 20000) return;
        if (seen[s.spanId]){ cyc = true; return; }
        seen[s.spanId] = 1;
        s.depth = d;
        if (d > depth) depth = d;
        for (var c = 0; c < s.children.length; c++) walk(s.children[c], d + 1, seen);
        delete seen[s.spanId];
      }
      tr.roots.concat(tr.orphans).forEach(function(s){ walk(s, 1, {}); });
      tr.depth = depth;
      tr.cyclic = cyc;
      tr.errorCount = tr.spans.filter(function(s){ return s.status === 'ERROR'; }).length;
      tr.services = {};
      tr.spans.forEach(function(s){ if (s.service) tr.services[s.service] = (tr.services[s.service] || 0) + 1; });
      out.push(tr);
    });
    out.sort(function(a, b){ return (b.spans.length - a.spans.length) || (a.traceId < b.traceId ? -1 : 1); });
    return out;
  }

  // ==================== 关键路径 ====================
  function criticalPath(trace){
    // 从耗时最长的根 span 出发，每层挑耗时最长的子 span
    var best = null;
    trace.roots.concat(trace.orphans).forEach(function(r){
      if (!best || (r.dur || 0) > (best.dur || 0)) best = r;
    });
    var path = [], guard = 0;
    var cur = best;
    while (cur && guard++ < 500){
      path.push(cur);
      var next = null;
      for (var i = 0; i < cur.children.length; i++)
        if (!next || (cur.children[i].dur || 0) > (next.dur || 0)) next = cur.children[i];
      cur = next;
    }
    var total = best && best.dur != null ? best.dur : null;
    return {total:total, steps:path.map(function(s){
      return {name:s.name, kind:s.kind, service:s.service, dur:s.dur,
              pct: (total && s.dur != null) ? (s.dur / total * 100) : null,
              status:s.status, depth:s.depth || 1};
    })};
  }

  // ==================== 体检 ====================
  function lint(parsed, traces){
    var out = [], spans = parsed.spans;
    function add(level, text){ out.push({level:level, text:text}); }
    var seenIds = {}, dupIds = {}, i, s;

    // 资源级
    for (i = 0; i < parsed.resources.length; i++){
      var res = parsed.resources[i];
      for (var q = 0; q < REQUIRED_RESOURCE.length; q++){
        if (res.attrs[REQUIRED_RESOURCE[q]] == null)
          add('err', '第 ' + (i + 1) + ' 组 resource 缺少必填属性 ' + REQUIRED_RESOURCE[q] +
                     '：后端会把这批 span 归到 unknown_service，服务拓扑直接崩掉');
      }
      var missRec = RECOMMENDED_RESOURCE.filter(function(k){ return res.attrs[k] == null; });
      if (missRec.length >= 3)
        add('info', '第 ' + (i + 1) + ' 组 resource 建议补上 ' + missRec.slice(0, 4).join('、') +
                    '：没有版本和环境标签，灰度对比与回归定位会很难做');
      if (res.attrs['deployment.environment'] != null && res.attrs['deployment.environment.name'] == null)
        add('warn', 'resource 用的是旧键 deployment.environment，稳定版语义约定已改名为 deployment.environment.name');
      if (res.dropped > 0)
        add('warn', '第 ' + (i + 1) + ' 组 resource 有 ' + res.dropped + ' 条属性被 SDK 丢弃：属性数量超限了');
    }

    // span 级
    for (i = 0; i < spans.length; i++){
      s = spans[i];
      var tag = '「' + (s.name || '(空名字)') + '」';

      if (!HEX32.test(s.traceId)) add('err', tag + ' 的 traceId 不是 32 位小写十六进制：' + (s.traceId || '(空)'));
      else if (s.traceId === ZERO32) add('err', tag + ' 的 traceId 全为 0，属于无效 ID，采集端会整条丢弃');
      if (!HEX16.test(s.spanId)) add('err', tag + ' 的 spanId 不是 16 位小写十六进制：' + (s.spanId || '(空)'));
      else if (s.spanId === ZERO16) add('err', tag + ' 的 spanId 全为 0，属于无效 ID');
      if (s.parentSpanId && s.parentSpanId !== ZERO16 && !HEX16.test(s.parentSpanId))
        add('err', tag + ' 的 parentSpanId 格式非法：' + s.parentSpanId);
      if (s.spanId && s.spanId === s.parentSpanId)
        add('err', tag + ' 的 parentSpanId 指向自己，会在后端形成自环');

      if (s.spanId){
        if (seenIds[s.spanId]) dupIds[s.spanId] = 1;
        seenIds[s.spanId] = 1;
      }
      if (!s.name) add('err', '存在没有 name 的 span：UI 上会显示成空白条');

      if (s.start == null || s.end == null) add('err', tag + ' 缺少 startTimeUnixNano 或 endTimeUnixNano');
      else {
        if (s.end < s.start) add('err', tag + ' 的结束时间早于开始时间，时长为负数');
        else if (s.dur === 0) add('info', tag + ' 时长为 0 纳秒：多半是计时用了毫秒精度的时钟');
        if (s.dur != null && s.dur > 3600 * 1e9)
          add('warn', tag + ' 时长超过 1 小时（' + fmtDur(s.dur) + '）：检查是不是漏调了 end()，泄漏的 span 会一直占内存');
        // 纳秒量级校验：2001-09-09 之后、2100 年之前
        if (s.start > 0 && s.start < 1e18)
          add('warn', tag + ' 的 startTimeUnixNano 看起来不是纳秒（值偏小），OTLP 要求 Unix 纳秒时间戳');
      }

      if (s.status === 'ERROR' && !s.statusMsg)
        add('info', tag + ' 状态是 ERROR 但没有 status.message：排障时看不到失败原因');
      if (s.status === 'OK' && s.kind === 'SERVER')
        add('info', tag + ' 显式设置了 status OK：语义约定建议只有 SERVER 端明确判定成功才这么写，通常留 UNSET 即可');

      // 属性体检
      var keys = Object.keys(s.attrs);
      if (keys.length > 64)
        add('warn', tag + ' 带了 ' + keys.length + ' 个属性：多数后端对单 span 属性数有上限，超出会被截断');
      for (var a = 0; a < keys.length; a++){
        var k = keys[a], v = s.attrs[k];
        if (RENAMED[k])
          add('warn', tag + ' 使用了旧属性名 ' + k + '，稳定版语义约定已改为 ' + RENAMED[k]);
        if (SECRET_RE.test(k))
          add('err', tag + ' 的属性 ' + k + ' 疑似携带凭据：trace 会长期留存并被广泛检索，绝不能放密钥');
        if (typeof v === 'string'){
          if (SECRET_VAL.test(v))
            add('err', tag + ' 的属性 ' + k + ' 的值看起来是令牌或密钥，请在导出前脱敏');
          if (v.length > 1024)
            add('warn', tag + ' 的属性 ' + k + ' 值长达 ' + v.length + ' 字符：会显著抬高存储与传输成本，建议截断');
        }
        if (/^[A-Z0-9_]+$/.test(k) && k.length > 2)
          add('info', tag + ' 的属性名 ' + k + ' 用了大写下划线风格：语义约定要求小写点分命名，例如 http.request.method');
      }

      // 按 kind 检查语义约定
      var isHttp = keys.some(function(x){ return x.indexOf('http.') === 0 || x === 'url.full' || x === 'url.path'; });
      if (isHttp){
        var method = s.attrs['http.request.method'] != null ? s.attrs['http.request.method'] : s.attrs['http.method'];
        if (method == null)
          add('warn', tag + ' 是 HTTP span 但没有 http.request.method：这是稳定版语义约定里的必填项');
        if (s.kind === 'SERVER' && s.attrs['http.route'] == null && s.attrs['url.path'] == null && s.attrs['http.target'] == null)
          add('info', tag + ' 是 HTTP 服务端 span 但没有 http.route：没有路由模板就没法按接口聚合');
        var code = num(s.attrs['http.response.status_code'] != null ? s.attrs['http.response.status_code'] : s.attrs['http.status_code']);
        if (code != null && code >= 500 && s.status !== 'ERROR')
          add('warn', tag + ' 返回了 ' + code + ' 却没有把 span 状态置为 ERROR：错误率统计会漏报');
        if (code != null && code >= 400 && code < 500 && s.status === 'ERROR' && s.kind === 'SERVER')
          add('info', tag + ' 把 4xx 记成了 ERROR：语义约定规定服务端的 4xx 不算服务端错误，只有客户端 span 才应标 ERROR');
        // 高基数 URL 直接进 span 名
        if (s.kind === 'SERVER' && /\/\d{3,}|[0-9a-f]{8}-[0-9a-f]{4}/.test(s.name))
          add('warn', tag + ' 的 span 名里嵌了 ID 或 UUID：这会造成高基数，应改用 http.route 模板作为名字');
      }
      var isDb = keys.some(function(x){ return x.indexOf('db.') === 0; });
      if (isDb){
        if (s.attrs['db.system'] == null && s.attrs['db.system.name'] == null)
          add('warn', tag + ' 是数据库 span 但缺 db.system.name：后端无法判断这是 MySQL 还是 Redis');
        var q = s.attrs['db.query.text'] != null ? s.attrs['db.query.text'] : s.attrs['db.statement'];
        if (typeof q === 'string' && /'[^']{0,64}'|=\s*\d{3,}/.test(q))
          add('warn', tag + ' 的 SQL 里带了字面量参数：语义约定要求把值替换成占位符，否则既泄漏数据又打爆基数');
        if (s.kind !== 'CLIENT')
          add('info', tag + ' 是数据库调用却不是 CLIENT kind：调用方视角的 span 应该是 CLIENT');
      }
      var isRpc = keys.some(function(x){ return x.indexOf('rpc.') === 0; });
      if (isRpc && s.attrs['rpc.system'] == null)
        add('warn', tag + ' 是 RPC span 但缺 rpc.system');
      var isMsg = keys.some(function(x){ return x.indexOf('messaging.') === 0; });
      if (isMsg && s.attrs['messaging.system'] == null)
        add('warn', tag + ' 是消息 span 但缺 messaging.system');

      // 异常事件
      for (var e = 0; e < s.events.length; e++){
        var ev = s.events[e];
        if (ev.name === 'exception'){
          if (ev.attrs['exception.type'] == null)
            add('warn', tag + ' 的 exception 事件缺 exception.type');
          if (s.status !== 'ERROR')
            add('warn', tag + ' 记录了 exception 事件却没有把状态置为 ERROR');
          var stk = ev.attrs['exception.stacktrace'];
          if (typeof stk === 'string' && stk.length > 4096)
            add('info', tag + ' 的堆栈长达 ' + stk.length + ' 字符：建议截断，堆栈往往是 trace 体积的大头');
        }
        if (ev.time != null && s.start != null && s.end != null && (ev.time < s.start || ev.time > s.end))
          add('warn', tag + ' 的事件「' + ev.name + '」时间落在 span 区间之外');
      }
      if (s.events.length > 128)
        add('warn', tag + ' 挂了 ' + s.events.length + ' 个事件：多数 SDK 默认上限是 128，超出会被丢弃');
      if (s.droppedAttrs || s.droppedEvents || s.droppedLinks)
        add('warn', tag + ' 有被 SDK 丢弃的数据：属性 ' + s.droppedAttrs + ' / 事件 ' + s.droppedEvents + ' / 链接 ' + s.droppedLinks);
      for (var l = 0; l < s.links.length; l++){
        if (!HEX32.test(s.links[l].traceId) || !HEX16.test(s.links[l].spanId))
          add('warn', tag + ' 的第 ' + (l + 1) + ' 条 link 指向了非法 ID');
      }
    }

    Object.keys(dupIds).forEach(function(id){
      add('err', 'spanId ' + id + ' 出现了多次：span ID 必须在 trace 内唯一，重复会让链路树错乱');
    });

    // trace 级
    for (i = 0; i < traces.length; i++){
      var tr = traces[i];
      var short = tr.traceId.slice(0, 8);
      if (!tr.roots.length)
        add('warn', 'trace ' + short + '… 没有根 span：要么采集不完整，要么上游把 parentSpanId 传错了');
      if (tr.roots.length > 1)
        add('info', 'trace ' + short + '… 有 ' + tr.roots.length + ' 个根 span：通常意味着上下文在某处断开后各自新建了链路');
      if (tr.orphans.length)
        add('warn', 'trace ' + short + '… 有 ' + tr.orphans.length + ' 个孤儿 span，它们的父 span 不在这批数据里');
      if (tr.cyclic)
        add('err', 'trace ' + short + '… 的父子关系里存在环');
      // 子 span 超出父 span 时间区间
      tr.spans.forEach(function(p){
        for (var c = 0; c < p.children.length; c++){
          var ch = p.children[c];
          if (p.start != null && ch.start != null && ch.start < p.start - 1e6)
            add('warn', '「' + ch.name + '」比父 span「' + p.name + '」还早开始，多半是多机时钟不同步');
          if (p.end != null && ch.end != null && ch.end > p.end + 1e6)
            add('warn', '「' + ch.name + '」比父 span「' + p.name + '」还晚结束，检查是否漏了 end() 或异步 span 没接好上下文');
        }
      });
      if (tr.spans.length > 2000)
        add('warn', 'trace ' + short + '… 有 ' + tr.spans.length + ' 个 span：超大 trace 会拖垮后端 UI，考虑抽样或收敛循环内埋点');
      if (tr.depth > 40)
        add('info', 'trace ' + short + '… 深度达到 ' + tr.depth + ' 层：过深的链路往往是递归或框架层层包裹产生的噪声');
    }
    return out;
  }

  // ==================== 体积估算 ====================
  function payload(parsed){
    var attrBytes = 0, evBytes = 0, nameBytes = 0, n = 0, attrCount = 0, evCount = 0;
    parsed.spans.forEach(function(s){
      n++;
      nameBytes += (s.name || '').length;
      Object.keys(s.attrs).forEach(function(k){
        attrCount++;
        attrBytes += k.length + String(s.attrs[k] == null ? '' : s.attrs[k]).length + 8;
      });
      s.events.forEach(function(e){
        evCount++;
        evBytes += (e.name || '').length + 16;
        Object.keys(e.attrs).forEach(function(k){ evBytes += k.length + String(e.attrs[k] == null ? '' : e.attrs[k]).length + 8; });
      });
    });
    var fixed = n * 60; // ID、时间戳、kind、status 的粗略固定开销
    var total = fixed + nameBytes + attrBytes + evBytes;
    return {
      spans: n, attrCount: attrCount, eventCount: evCount,
      bytes: total, perSpan: n ? Math.round(total / n) : 0,
      attrBytes: attrBytes, eventBytes: evBytes, fixedBytes: fixed,
      dailyGB1k: +(total / Math.max(1, n) * 1000 * 86400 / 1e9).toFixed(2) // 1000 span/s 时每天的 GB 数
    };
  }

  function summary(parsed, traces){
    var svc = {}, kinds = {}, errs = 0, durs = [];
    parsed.spans.forEach(function(s){
      var k = s.service || '(未命名服务)';
      svc[k] = (svc[k] || 0) + 1;
      kinds[s.kind] = (kinds[s.kind] || 0) + 1;
      if (s.status === 'ERROR') errs++;
      if (s.dur != null && s.dur >= 0) durs.push(s.dur);
    });
    durs.sort(function(a, b){ return a - b; });
    function pct(p){
      if (!durs.length) return null;
      var idx = Math.min(durs.length - 1, Math.max(0, Math.ceil(p / 100 * durs.length) - 1));
      return durs[idx];
    }
    return {
      spanCount: parsed.spans.length,
      traceCount: traces.length,
      serviceCount: Object.keys(svc).length,
      services: Object.keys(svc).sort(function(a, b){ return svc[b] - svc[a]; }).map(function(k){ return {name:k, count:svc[k]}; }),
      kinds: kinds,
      errorCount: errs,
      errorRate: parsed.spans.length ? +(errs / parsed.spans.length * 100).toFixed(2) : 0,
      p50: pct(50), p95: pct(95), p99: pct(99), max: durs.length ? durs[durs.length - 1] : null,
      scopes: Object.keys(parsed.scopes).map(function(k){ return parsed.scopes[k]; })
    };
  }

  function analyze(text){
    var p = parse(text);
    if (p.error) return {error:p.error};
    var traces = buildTrees(p.spans);
    var issues = lint(p, traces);
    return {
      summary: summary(p, traces),
      traces: traces.map(function(t){
        return {
          traceId: t.traceId, spans: t.spans.length, roots: t.roots.length,
          orphans: t.orphans.length, depth: t.depth, cyclic: t.cyclic,
          duration: t.duration, durationText: fmtDur(t.duration),
          errorCount: t.errorCount,
          services: Object.keys(t.services).map(function(k){ return {name:k, count:t.services[k]}; }),
          critical: criticalPath(t)
        };
      }),
      payload: payload(p),
      issues: issues,
      errCount: issues.filter(function(x){ return x.level === 'err'; }).length,
      warnCount: issues.filter(function(x){ return x.level === 'warn'; }).length
    };
  }

  var api = {parse:parse, buildTrees:buildTrees, criticalPath:criticalPath, lint:lint,
             payload:payload, summary:summary, analyze:analyze,
             anyValue:anyValue, attrMap:attrMap, fmtDur:fmtDur, RENAMED:RENAMED};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {OtelForgePure:OtelForgePure}; }
  return api;
}
